-- Generated by `pannes ddl` from src/pannes/kpi.py. Do not edit by hand.

CREATE OR ALTER VIEW v_pannes_detail AS
SELECT p.panne_id, p.date_panne, CONVERT(char(7), p.date_panne, 126) AS mois,
       e.code AS equipement, e.designation AS type_equipement, s.nom AS site,
       pc.nom AS piece, p.gravite, p.source,
       (DATEDIFF(minute, p.date_panne, p.date_declaration) / 60.0) AS delai_declaration_h,
       (DATEDIFF(minute, p.date_panne, p.date_fin) / 60.0) AS duree_reparation_h,
       CASE WHEN p.date_declaration IS NOT NULL AND (DATEDIFF(minute, p.date_panne, p.date_declaration) / 60.0) > 24.0 THEN 1 ELSE 0 END
           AS declaration_tardive
FROM pannes p
JOIN equipements e ON e.equipement_id = p.equipement_id
JOIN sites s ON s.site_id = e.site_id
JOIN pieces pc ON pc.piece_id = p.piece_id;
GO

CREATE OR ALTER VIEW v_kpi_piece AS
SELECT piece,
       COUNT(*) AS nb_pannes,
       COUNT(DISTINCT equipement) AS nb_equipements_touches,
       COUNT(*) / (((DATEDIFF(minute, (select min(date_panne) from pannes), (select max(date_panne) from pannes)) / 60.0)) / (24.0 * 30.4375)) AS pannes_par_mois,
       AVG(duree_reparation_h) AS mttr_h,
       AVG(CASE WHEN gravite = 'critique' THEN 1.0 ELSE 0.0 END) AS part_critique
FROM v_pannes_detail
GROUP BY piece;
GO

CREATE OR ALTER VIEW v_kpi_equipement AS
SELECT equipement, type_equipement, site,
       COUNT(*) AS nb_pannes,
       AVG(duree_reparation_h) AS mttr_h,
       (((DATEDIFF(minute, (select min(date_panne) from pannes), (select max(date_panne) from pannes)) / 60.0)) - SUM(COALESCE(duree_reparation_h, 0))) / COUNT(*) AS mtbf_h,
       1.0 - SUM(COALESCE(duree_reparation_h, 0)) / ((DATEDIFF(minute, (select min(date_panne) from pannes), (select max(date_panne) from pannes)) / 60.0)) AS disponibilite
FROM v_pannes_detail
GROUP BY equipement, type_equipement, site;
GO

CREATE OR ALTER VIEW v_kpi_mensuel AS
SELECT mois, site,
       COUNT(*) AS nb_pannes,
       AVG(delai_declaration_h) AS delai_moyen_h,
       AVG(1.0 * declaration_tardive) AS part_tardives
FROM v_pannes_detail
GROUP BY mois, site;
GO
